const fs=require('fs'),p=require('path'),c=require('crypto');
const Q='/Volumes/AI_DATA/development/det-review-evidence/ri172-full-layer-implication-6n1jflgq',P='/Volumes/AI_DATA/development/det-review-evidence/ri168-terminal-row-coupling-f50p8xyj';
const eq=(a,b)=>JSON.stringify(a)===JSON.stringify(b), need=(b,m)=>{if(!b)throw Error(m)}, cache=new Map(), fields=['dev','ino','mode','size','mtimeNs','ctimeNs','nlink'];
function read(x){if(cache.has(x))return cache.get(x);need(p.isAbsolute(x)&&p.normalize(x)===x,'path '+x);let t='/';for(const k of x.split('/').filter(Boolean)){t=p.join(t,k);need(!fs.lstatSync(t).isSymbolicLink(),'link '+x);}const st=fs.lstatSync(x,{bigint:true}),same=a=>fields.every(k=>a[k]===st[k]);need(st.isFile()&&st.size<=67108864n,'regular/cap');const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'fd-before');const chunks=[];let length=0;const cap=Number(st.size)+1;while(length<cap){const block=Buffer.alloc(Math.min(65536,cap-length));const got=fs.readSync(fd,block,0,block.length,null);if(!got)break;chunks.push(block.subarray(0,got));length+=got;}b=Buffer.concat(chunks);need(b.length===Number(st.size),'size drift');need(same(fs.fstatSync(fd,{bigint:true})),'fd-after');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'path-after');const r={body:b,path:x,resolved_path:x,bytes:b.length,sha256:c.createHash('sha256').update(b).digest('hex'),symlinks:[],state:Object.fromEntries(fields.map(k=>[k,st[k].toString()]))};cache.set(x,r);return r;}
function pin(i){const a=read(i.path);for(const k of ['path','bytes','sha256'])need(a[k]===i[k],'pin '+i.path);if(i.resolved_path!==undefined)need(a.resolved_path===i.resolved_path,'resolved');if(i.symlinks!==undefined)need(eq(a.symlinks,i.symlinks),'symlinks');if(i.symlink_chain!==undefined)need(eq(a.symlinks,i.symlink_chain),'symlink_chain');return a;}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

pin({path:Q+'/SOURCE_DEPENDENCIES.json',bytes:251680,sha256:'f717afae902b128903210a6ab9637a10dd23a5e2003f272ea302506ed3b217d4'});
pin({path:Q+'/SOURCE_IDENTITIES.json',bytes:52126,sha256:'1d3a4761ef0a25f52e7448377b2d212e578488ffc5a1c1ccc9a0bcf07a775925'});
pin({"path":"/Volumes/AI_DATA/development/det-review-evidence/ri172-full-layer-implication-6n1jflgq/DEPENDENCY_NOTES.md","bytes":15289,"sha256":"76cc092ba4dc7a2eeacd68182a8250b3c1ca115dcf37e9f0eade6e8b3f88ae68"});
const D=JSON.parse(read(Q+'/SOURCE_DEPENDENCIES.json').body),S=JSON.parse(read(Q+'/SOURCE_IDENTITIES.json').body),M=new Map(D.protected_files.map(r=>[r.path,r]));
need(M.size===276&&eq([...M.keys()],[...M.keys()].sort()),'count/sort');
D.protected_files.forEach((r,i)=>{need(r.role==='dep_'+String(i+1).padStart(4,'0')&&r.path===r.identity.path,'row');pin(r.identity)});
need(D.protected_files.reduce((n,r)=>n+r.identity.bytes,0)===17408176,'total selected bytes');
const old=JSON.parse(read(P+'/SOURCE_DEPENDENCIES.json').body),oldS=JSON.parse(read(P+'/SOURCE_IDENTITIES.json').body),omit=r=>Object.fromEntries(Object.entries(r).filter(([k])=>k!=='role'));
need(old.protected_files.length===264,'old264');for(const r of old.protected_files)need(eq(omit(r),omit(M.get(r.path))),'inherited row');
need(eq(D.governance_stopping_boundary,old.governance_stopping_boundary),'inherited boundary');
for(const k of ['premise_texts','actual_source_text_reads','source_text_counterparts','immutable_numerical_certificate','unchanged_obligations'])need(eq(S[k],oldS[k]),'inherited S '+k);
const prior=JSON.parse(read(P+'/HANDOFF.json').body),priorNames=fs.readdirSync(P).sort();
need(priorNames.length===8&&eq(priorNames,[...prior.namespace].sort())&&eq(priorNames,[...prior.payloads.map(i=>p.basename(i.path)),'HANDOFF.json'].sort()),'predecessor namespace');prior.payloads.forEach(pin);
need(eq(D.historical_phase_record_boundary,old.historical_phase_record_boundary)&&eq(D.historical_phase_record_boundary,S.governance.RI166_phase_record_boundary),'inherited phase boundary');
const phase=M.get(D.historical_phase_record_boundary.path);need(phase.classification==='opaque-historical-acceptance-or-source-support'&&D.historical_phase_record_boundary.typed_reference_expansion===false,'phase routing');
const support=M.get(P+'/AUTHOR_CHECKS.json');need(support.classification==='opaque-historical-acceptance-or-source-support'&&D.predecessor_author_support_boundary.path===support.path&&D.predecessor_author_support_boundary.typed_reference_expansion===false&&eq(D.predecessor_author_support_boundary,S.governance.RI168_author_support_boundary),'new author support boundary');
let refs=0,extended=0,states=0;function scan(x){if(!x||typeof x!=='object')return;if(!Array.isArray(x)&&typeof x.path==='string'&&Number.isSafeInteger(x.bytes)&&typeof x.sha256==='string'){need(M.has(x.path)||x.path===Q+'/SOURCE_DEPENDENCIES.json','reference closure '+x.path);pin(x);refs++;if(x.symlink_chain!==undefined)extended++;if(x.state!==undefined)states++;}Object.values(x).forEach(scan)}
const governance='/Volumes/AI_DATA/development/det-review-evidence/ri164-root-static-review-xr1qffz8/RI164_ROOT_ADJUDICATION.json';
need(D.governance_stopping_boundary.path===governance&&D.governance_stopping_boundary.typed_reference_expansion===false&&eq(D.governance_stopping_boundary,S.governance.operational_stopping_boundary),'governance rule');
let admin=0,boundary=0;
for(const r of D.protected_files)if(r.classification==='selected-administrative-proof-provenance'){admin++;scan(JSON.parse(read(r.path).body))}else if(r.classification==='selected-administrative-governance-boundary'){boundary++;need(r.path===governance,'exact governance boundary')}
need(admin===98&&boundary===1&&refs===2741&&extended===17&&states===17,'historical reference counts');
refs=0;scan(S);need(refs===123,'current S references');
for(const[k,i]of Object.entries(S.source_text_counterparts.published))need(read(i.path).body.equals(read(S.premise_texts[k].path).body),'separate path byte equality');
const final=['FULL_LAYER_PATH.md','NONIMPLICATION.md','DEPENDENCY_NOTES.md','SOURCE_DEPENDENCIES.json','SOURCE_IDENTITIES.json','HANDOFF.md','AUTHOR_CHECKS.json','HANDOFF.json'].sort(),stage=process.argv[1]||'preseal6';
need(['preseal6','final8'].includes(stage),'stage');
const expected=stage==='final8'?final:final.filter(n=>!['AUTHOR_CHECKS.json','HANDOFF.json'].includes(n));
need(eq(fs.readdirSync(Q).sort(),expected),'current namespace');
const payloads=expected.map(n=>simple(read(Q+'/'+n)));let references=0;
for(const n of ['FULL_LAYER_PATH.md','NONIMPLICATION.md','DEPENDENCY_NOTES.md','HANDOFF.md']){
 const txt=read(Q+'/'+n).body.toString('utf8');need(!/^(<{7}|={7}|>{7})( |$)/m.test(txt),'conflict marker');need(!/[ \t]+$/m.test(txt),'trailing whitespace');
 for(const m of txt.matchAll(/(\/Volumes\/[^\s\x60|]+\.(?:md|json|py))(?:[\s\x60|]|$)/g)){need(M.has(m[1])||expected.some(f=>Q+'/'+f===m[1]),'literal source path '+m[1]);references++}
 for(const m of txt.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){need(!m[1].includes('://')&&expected.includes(m[1]),'current markdown link '+m[1]);read(Q+'/'+m[1])}
}
if(stage==='final8'){
 const h=JSON.parse(read(Q+'/HANDOFF.json').body);need(eq(h.namespace,final)&&h.payloads.length===7,'current seal');
 need(eq(h.payloads.map(i=>p.basename(i.path)).sort(),final.filter(n=>n!=='HANDOFF.json')),'seal coverage');h.payloads.forEach(pin);pin(h.assignment);pin(h.accepted_analytic_predecessor);pin(h.operational_governance_predecessor);
 need(h.complete_finite_layer_nonimplication_proved===true&&h.fixed_actual_law_counterexample_claimed===false&&h.higher_layer_preservation_claimed===false&&h.actual_109_vector_read===false,'result scope');
}
const before=[...cache.values()].map(simple);cache.clear();before.forEach(pin);
need(eq(fs.readdirSync(Q).sort(),expected),'end namespace');need(eq(fs.readdirSync(P).sort(),priorNames),'end predecessor namespace');
console.log(JSON.stringify({schema:'ri172-author-administrative-check-v1',status:'MATCH_NOT_MATHEMATICAL_OR_OPERATIONAL_ACCEPTANCE',stage,dependencies:276,selected_bytes:17408176,inherited:264,administrative_full_bodies:98,governance_only_boundaries:1,historical_author_check_phase_opaque:true,predecessor_author_support_opaque:true,historical_typed_references:2741,current_typed_references:123,historical_extended_state_noncomparisons:17,separate_byte_equal_pairs:4,predecessor_namespace_counts:[8],current_namespace:expected.length,literal_manuscript_reference_occurrences:references,final_fresh_identity_rechecks:before.length,current_payloads:payloads,mathematical_formula_evaluated_by_script:false,scientific_or_target_execution:false},null,2));
